/// Runtime string → index. `None` if unknown.
/// **Not** for Kani (O(n) compare). Use [`card_id!`] there.
pub fn card_id_opt(id: &str) -> Option<usize> {
    let mut i = 0usize;
    while i < CARD_COUNT {
        if IDS[i] == id {
            return Some(i);
        }
        i += 1;
    }
    None
}

/// Runtime string → index. Panics on an unknown id.
pub fn card_id_const(id: &str) -> usize {
    match card_id_opt(id) {
        Some(i) => i,
        None => panic!("card_id!: unknown id {id}"),
    }
}

